cd $R && nice -n 10 /scratch/jjyeung/envs/p1cpu/bin/python -I - <<'PY'
import sqlite3,json,glob
Bd=json.load(open(glob.glob('0d28*')[0])); bt=set(Bd['train_scenes'])
rm={json.loads(l)['row_key'] for l in open('rm601.jsonl')}
c=sqlite3.connect('file:/scratch/jjyeung/n30_mirror/rows_r1/out/a2_vqa_v7/vqa/rows.sqlite?mode=ro',uri=True)
out=set()
for (row,) in c.execute('select row from rows'):
    r=json.loads(row)
    if f"{r.get('dataset')}/{r.get('scene')}" not in bt: out.add(r.get('qid'))
print('outside 0d28 train',len(out),'removal keys',len(rm),'equal',out==rm,'out-rm',len(out-rm),'rm-out',len(rm-out))
PY
